// APT repository at apt.davamu.dev. The signed indexes and the public key are static assets of this Worker (public/,
// generated by update-repository.sh) and never reach this code; the packages listed in them are redirected to the
// release assets on GitHub, so no package is stored on Cloudflare.

// pool/main/filebot-pro_1.2.3_amd64.deb (or 1.2.3-1, the Debian revision is not part of the tag)
const PACKAGE = /^\/pool\/main\/(filebot-pro_(\d[\w.+~]*?)(?:-\d+)?_[a-z0-9]+\.deb)$/;

export default {
	async fetch(request, env) {
		const { pathname } = new URL(request.url);

		const match = PACKAGE.exec(pathname);
		if (match) {
			const [, file, version] = match;
			return Response.redirect(`https://github.com/${env.GITHUB_REPOSITORY}/releases/download/v${version}/${file}`, 302);
		}

		if (pathname === '/') {
			return Response.redirect(env.INSTALL_GUIDE, 302);
		}

		return new Response('Not found\n', { status: 404 });
	},
};
